def gen(rng):
    def fmt(k, a):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))
    tests = [fmt(1, [1]), fmt(15, [10**9]), fmt(1, [5, 5]), fmt(3, [1, 1, 1]), fmt(2, [8, 1, 2]),
             fmt(1, [2, 1]), fmt(4, [7, 3, 12, 1])]
    for n in (2, 3, 4, 5):
        for _ in range(5):
            k = rng.randint(1, 5)
            hi = rng.choice([7, 31, 100, 1000])
            tests.append(fmt(k, [rng.randint(1, hi) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt(rng.randint(1, 5), [1 << rng.randint(0, 9) for _ in range(5)]))
    tests.append(fmt(15, [rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt(15, [10**9] * 100000))
    tests.append(fmt(14, [rng.randint(1, 1000) for _ in range(100000)]))
    tests.append(fmt(15, [1 << rng.randint(0, 29) for _ in range(100000)]))
    return tests

